  }

  /* Gestures (only on the island itself):
       short swipe left/right = next/previous route
       long swipe left/right  = Bus End (dismiss): 90 dp, or 60 dp if fast
                                (decideSwipe, shared with scripts/swipe.js); the
                                island follows your finger and fades, and gives a
                                small buzz once the swipe is long enough
       long press             = the next nearby stop (Bus Island)
     Pointer capture keeps following the finger after it leaves the 30 dp
     island, and a gesture is judged on release OR cancel (Android can cancel
     a touch near the top of the screen). */
  /* ==================================================================
     The island · What a sideways swipe means
     Shared, word for word, by the island's page (island_show.js) and the
     tests. dx: sideways movement in dp (negative = left); ms: how long it
     took. Route change: from 24 dp. Dismiss: from 90 dp, or from 60 dp if
     it's a fast fling (0.6 dp per ms or more). Anything shorter: nothing.
     Returns 'next', 'previous', 'dismiss' or 'none'.
     ================================================================== */
  /* ==================================================================
     The island · What a sideways swipe means
     Shared, word for word, by the island's page (island_show.js) and the
     tests. dx: sideways movement in dp (negative = left); ms: how long it
     took. Route change: from 24 dp. Dismiss: from 90 dp, or from 60 dp if
     it's a fast fling (0.6 dp per ms or more). Anything shorter: nothing.
     Returns 'next', 'previous', 'dismiss' or 'none'.
     ================================================================== */
  function decideSwipe(dx, ms) {
    var dist = Math.abs(dx); var speed = dist / Math.max(1, ms);
    if (dist < 24) return 'none';
    if (dist >= 90 || (dist >= 60 && speed >= 0.6)) return 'dismiss';
    return dx < 0 ? 'next' : 'previous';
  }
  var sx = 0, sy = 0, lx = 0, ly = 0, t0 = 0, down = false, held = false, armed = false, holdTimer = null;
  function follow(dx) {                  // past 24 dp the island follows your finger, fading towards 90 dp
    var past = Math.max(0, Math.abs(dx) - 24) * (dx < 0 ? -1 : 1);
    p.style.transition = 'none';
    p.style.transform = 'translateX(' + Math.max(-120, Math.min(120, past)) + 'px)';
    p.style.opacity = String(Math.max(0.35, 1 - Math.max(0, Math.abs(dx) - 24) / 110));
  }
  function settle() { p.style.transition = 'transform .15s, opacity .15s'; p.style.transform = ''; p.style.opacity = '1'; }
  function judge() {
    clearTimeout(holdTimer);
    if (!down) return;
    down = false;
    var dx = lx - sx, dy = ly - sy, wasArmed = armed;
    armed = false;
    settle();
    if (held) return;
    if (Math.abs(dx) <= Math.abs(dy)) return;                  // mostly up or down: not a swipe
    var what = decideSwipe(dx, Date.now() - t0);
    if (what === 'dismiss') runTask('Bus End');
    else if (what === 'next') go(1);
    else if (what === 'previous') go(-1);
  }
  p.addEventListener('pointerdown', function (e) {
    sx = lx = e.clientX; sy = ly = e.clientY; t0 = Date.now(); down = true; held = false; armed = false;
    try { p.setPointerCapture(e.pointerId); } catch (err) {}
    holdTimer = setTimeout(function () {
      held = true;
      runTask('Bus Island', { busfrom: 'island', busisland: 'switch' });
    }, HOLD);
  });
  p.addEventListener('pointermove', function (e) {
    if (!down) return;
    lx = e.clientX; ly = e.clientY;
    var dx = lx - sx;
    if (Math.abs(dx) > 10 || Math.abs(ly - sy) > 10) clearTimeout(holdTimer);
    if (held) return;
    var nowArmed = decideSwipe(dx, 1e9) === 'dismiss';            // far enough to dismiss even slowly (90 dp)
    if (nowArmed && !armed) runTask('Bus Island', { busfrom: 'island', busisland: 'buzz' });                // a tick when letting go will dismiss
    armed = nowArmed;
    if (Math.abs(dx) > 10) follow(dx);
  });
  p.addEventListener('pointerup', function (e) { lx = e.clientX; ly = e.clientY; judge(); });
  p.addEventListener('pointercancel', judge);
  p.addEventListener('contextmenu', function (e) { e.preventDefault(); });

  // Start: watch for new data, keep minutes current, animate the border
  new MutationObserver(read).observe(dataEl, { childList: true, characterData: true, subtree: true });
  window.addEventListener('resize', drawRing);
  setInterval(read, 1000);
  setInterval(draw, 15000);
  read();
  tick();
{{END_SCRIPT}}
</body>
</html>`;

function fill(page, values) {
  Object.keys(values).forEach(function (k) { page = page.split('{{' + k + '}}').join(String(values[k])); });
  return page;
}
var html = fill(PAGE, {
  H: H, PAD: PAD, RADIUS: H / 2, LEFT: LEFT, GAP: GAP, RIGHT: RIGHT, TOTAL: PAD + LEFT + GAP + RIGHT + PAD,
  SHAPE: CHIP ? 'chip' : 'island',
  PREVIEW: PREVIEW ? 'true' : 'false',
  BORDER: global('BusBorder') === 'on' ? 'true' : 'false',
  DATA: '%' + DATA_VAR,                      // split so Tasker doesn't fill it in here
  END_SCRIPT: '</' + 'script>'        // split for the same reason as above, for the HTML parser
});

/* ---- Scene V2 layout ----------------------------------------------
   A rounded clip at both ends of the modifier list keeps the WebView's
   corners see-through whichever way Tasker stacks modifiers. The
   WebView must not be darkened, or it paints a dark rectangle. */
var buslayout = JSON.stringify({
  name: 'Bus Pill',
  defaultDisplayMode: 'Overlay',
  root: {
    type: 'Box', id: 'root',
    modifiers: [
      { type: 'FillSize' },
      { type: 'Clip', shape: 'Rounded', radius: '50' },
      { type: 'Clip', shape: 'Rounded', radius: '50' }
    ],
    children: [{
      type: 'WebView', id: 'pillweb', content: html,
      backgroundColor: 'transparent', darkMode: 'ForceLight', supportZoom: 'false',
      modifiers: [{ type: 'FillSize' }]
    }]
  }
});

/* Bus Find Camera · If route 1's cutout step failed, keep Tasker's error message for the report */
// One of this task's local variables (Tasker passes them in as plain variables), trimmed, or '' if it
// isn't set
function loc(n) { try { var v = eval('typeof ' + n + ' === "undefined" ? "" : ' + n); return (v === null || String(v).charAt(0) === '%') ? '' : String(v).trim(); } catch (e) { return ''; } }
var buscuterr = loc('errmsg').slice(0, 120);

/* ==================================================================
   Bus Find Camera · Where is the camera?
   Reads what the Java Function steps above got from Android:
     busrects   = the display cutout's bounding rectangles, e.g.
                  "[Rect(612, 26 - 732, 110)]" (pixels)
     busmetrics = the display metrics, e.g.
                  "DisplayMetrics{density=3.0, width=1344, height=2992, ...}"
   and turns them into dp settings for the island:
     BusCameraX   = camera centre, from the left edge
     BusScreenW   = screen width
     BusIslandGap = camera width plus a small margin each side
     BusIslandY   = top of the island, so its middle lines up with the camera
   If anything is missing (no cutout, or the calls failed), nothing is changed.
   Output: busfound (message)
   ================================================================== */
function text(v) { return (v === undefined || v === null || String(v).charAt(0) === '%') ? '' : String(v); }
// Two routes to the same information (display service, then window service); use whichever worked
var rectsText = text(typeof busrects === 'undefined' ? undefined : busrects);
if (!/Rect\(/.test(rectsText)) rectsText = text(typeof busrects2 === 'undefined' ? undefined : busrects2);
var metricsText = text(typeof busmetrics === 'undefined' ? undefined : busmetrics);
var r = rectsText.match(/Rect\((-?\d+),\s*(-?\d+)\s*-\s*(-?\d+),\s*(-?\d+)\)/);
var dens = metricsText.match(/density=([\d.]+)/);
var w = metricsText.match(/width=(\d+)/); var h = metricsText.match(/height=(\d+)/);

var busfound;
if (!r || !dens || !w) {
  // Say exactly what came back, so the next fix can be targeted
  busfound = 'Camera not found, so the island settings are unchanged. Android returned: cutout "' +
             (rectsText || 'nothing') .slice(0, 80) + '", screen "' + (metricsText || 'nothing').slice(0, 80) + '"' +
             (typeof buscuterr !== 'undefined' && buscuterr && String(buscuterr).charAt(0) !== '%' ? '. Error: ' + buscuterr : '');
} else {
  var d = parseFloat(dens[1]);
  var left = +r[1]; var top = +r[2]; var right = +r[3]; var bottom = +r[4];
  var screenPx = Math.min(+w[1], h ? +h[1] : +w[1]);           // portrait width
  var H = parseInt(global('BusIslandH'), 10) || 30;
  var camX = Math.round((left + right) / 2 / d);
  var camW = Math.round((right - left) / d);
  var camY = (top + bottom) / 2 / d;
  var gap = camW + 8;                                            // 4 dp either side (Android's rectangle already has some margin)
  var y = Math.max(0, Math.round(camY - H / 2));
  setGlobal('BusCameraX', String(camX));
  setGlobal('BusScreenW', String(Math.round(screenPx / d)));
  setGlobal('BusIslandGap', String(gap));
  setGlobal('BusIslandY', String(y));
  busfound = 'Camera found: ' + camW + ' dp wide, centred ' + camX + ' dp from the left (screen ' +
             Math.round(screenPx / d) + ' dp). Island gap set to ' + gap + ' dp, top to ' + y + ' dp.';
}

/* ==================================================================
   Bus Start · Settings
   The one place every setting is defined. Change any of them in
   Tasker's Variables tab (add it with + if it isn't listed). Empty or
   invalid values are replaced with the defaults below.
   Output: BusStateReady (global) = yes / no
   ================================================================== */
// A Tasker global variable, trimmed, or '' if it isn't set (Tasker leaves an unset variable as its own
// name, starting with %)
function get(n) { var v = global(n); return (v === undefined || v === null || String(v).charAt(0) === '%') ? '' : String(v).trim(); }
function atLeast(min) { return function (v) { return parseFloat(v) >= min; }; }

var SETTINGS = [
  // [ name,          default, valid when...           ]  what it does
  ['BusStyle',      'pill',  function (v) { return /^(pill|chip)$/.test(v); }],  // island, or the status bar chip
  ['BusRadius',     '300',   atLeast(50)],    // metres: how far Bus Start looks for stops
  ['BusRefresh',    '45',    atLeast(15)],    // seconds between TfL refreshes
  ['BusTimeout',    '30',    atLeast(1)],     // minutes before the countdown gives up
  ['BusRotate',     '6',     atLeast(2)],     // seconds each route shows on the island
  ['BusDestLetters', '3',   function (v) { return v === '3' || v === '6' || v === '10'; }],   // letters of the destination the island has room for
  ['BusIslandGap',  '42',    atLeast(0)],     // dp: space left over the camera
  ['BusNearRadius', '50',    atLeast(10)],    // metres: arrival distance for a newly saved stop
  ['BusChipX',      '76',    function (v) { var n = parseFloat(v); return n >= 0 && n <= 300; }],   // status bar chip: dp from the left
  ['BusApproach', 'both', function (v) { return /^(off|walk|both)$/.test(v); }],   // show stops you're heading towards
  ['BusApproachMin', '3', function (v) { return /^(2|3|5)$/.test(v); }],
  ['BusRecord', 'off', function (v) { return /^(on|off)$/.test(v); }],          // trip recorder (off unless you turn it on)         // ...this many minutes ahead
  ['BusLeaveShow', 'work', function (v) { return /^(off|work|home|both)$/.test(v); }],   // leaving which Wi-Fi shows the nearest stop
  ['BusGlanceFrom', '17:00', function (v) { return v === 'off' || /^\d{1,2}:\d{2}$/.test(v); }],   // heads-up at work: from (or off)
  ['BusGlanceTo',   '18:00', function (v) { return /^\d{1,2}:\d{2}$/.test(v); }],                  // and until
  ['BusBorder',     'off',   function (v) { return v === 'on' || v === 'off'; }],   // countdown border round the island
