SETTINGS.forEach(function (s) { if (!s[2](get(s[0]))) setGlobal(s[0], s[1]); });


/* Saved places should all be "type|id|name|lat|lon|radius". A line saved in the older
   "id|name|lat|lon|radius" form (no type) was being skipped, so it's repaired here, and
   stray spaces, blank lines and duplicate stops are removed. */
(function repairPlaces() {
  var raw = global('BusPlaces');
  if (raw === undefined || raw === null || String(raw).charAt(0) === '%' || !String(raw).trim()) return;
  var seen = {}; var out = [];
  String(raw).split(/\r?\n/).forEach(function (line) {
    line = line.trim();
    if (!line) return;
    var p = line.split('|').map(function (x) { return x.trim(); });
    if (p[0] !== 'bus' && p[0] !== 'rail' && p.length >= 4 && !isNaN(parseFloat(p[2])) && !isNaN(parseFloat(p[3]))) p = ['bus'].concat(p.slice(0, 5));
    if (seen[p[0] + p[1]]) return;
    seen[p[0] + p[1]] = true;
    out.push(p.join('|'));
  });
  if (out.join('\n') !== String(raw)) setGlobal('BusPlaces', out.join('\n'));
})();

var ready = get('TflKey') !== '' && get('BusRoutes') !== '';
setGlobal('BusStateReady', ready ? 'yes' : 'no');

/* ==================================================================
   Bus Start · Can we use the position Android just pushed?
   When Bus Moved starts a countdown (you've arrived, or just left home
   or work), the position it used is seconds old (BusStateLastFix), so
   there's no need to fetch another. Started any other way, or with a
   position over a minute old, Bus Start fetches one as usual.
   Output: busfixok (yes: use it), gl_latitude, gl_longitude,
           gl_time_seconds, busstale
   ================================================================== */
// One of this task's local variables (Tasker passes them in as plain variables), trimmed, or '' if it
// isn't set
function loc(n) { try { var v = eval('typeof ' + n + ' === "undefined" ? "" : ' + n); return (v === null || String(v).charAt(0) === '%') ? '' : String(v).trim(); } catch (e) { return ''; } }
// Why Bus Start is running: par1 (arrived / approach / leaving / glance), or, if that didn't come
// through, the note Bus Watch or Bus Moved left just before starting it (BusStateStartMode, "mode|time",
// used if under a minute old). Started any other way, it's a manual start.
var mode = loc('par1');
if (!mode) {
  var note = String(global('BusStateStartMode') || '').split('|');
  if (note[0] && Date.now() - (parseInt(note[1], 10) || 0) < 60000) mode = note[0];
}
