var gl_latitude = busfixok === 'yes' ? String(fix.lat) : '';
var gl_longitude = busfixok === 'yes' ? String(fix.lon) : '';
var gl_time_seconds = busfixok === 'yes' ? String(fix.t / 1000) : '';
