        : onWork ? 'on work Wi-Fi'
        : quietFar ? 'staying put away from your stops, checked under 2 minutes ago'
        : '';
var busdue = (byHand || why === '') ? 'yes' : 'no';

// For Bus Status: what this check decided, and why
setGlobal('BusStateWatchInfo', new Date().toTimeString().slice(0, 5) + ' ' +
  (fromWake ? '(screen on) ' : fromMoved ? '(position pushed) ' : '(by hand) ') +
  (busend === 'yes' ? 'ended the countdown: ' + why
   : busleave === 'yes' ? 'you left ' + (lastWifi === get('BusHomeWifi') ? 'home' : 'work') + ' Wi-Fi: started a countdown for your nearest stop'
   : busdue === 'yes' ? 'checked location' : 'skipped: ' + why));

// Debugging: keep the last 20 decisions in BusDebugLog (copied by the Bus Debugging task).
// A repeat of the previous entry, apart from numbers, is skipped.
function debugLog(msg) {
  var a = []; try { a = JSON.parse(global('BusDebugLog') || '[]'); } catch (e) {}
  var plain = function (t) { return String(t).replace(/^\S+ /, '').replace(/[\d.]+/g, '#'); };
  if (a.length && plain(a[a.length - 1]) === plain('x ' + msg)) return;
  a.push(new Date().toTimeString().slice(0, 8) + ' ' + msg);
  setGlobal('BusDebugLog', JSON.stringify(a.slice(-20)));
}
if (busend === 'yes' || busleave === 'yes' || !fromMoved) debugLog(get('BusStateWatchInfo').replace(/^\d\d:\d\d /, ''));

/* ==================================================================
   Location · Is the fix fresh?
   Android can hand back an old, saved position (for example indoors,
   or in the background). Older than 3 minutes (1 minute during a
   countdown), or none at all, counts as stale, and the next step tries
   again with GPS forced on.
   Output: busstale = yes / no
   ================================================================== */
var t = (typeof gl_time_seconds !== 'undefined') ? parseFloat(gl_time_seconds) : NaN;
var hasFix = typeof gl_latitude !== 'undefined' && !isNaN(parseFloat(gl_latitude));
// During a countdown a position must be under a minute old, so walking away is noticed promptly;
// otherwise 3 minutes will do
var countdownOn = global('BusStateRunning') === '1';
var maxAge = countdownOn ? 60 : 180;
var busstale = (!hasFix || !(t > 0) || Date.now() / 1000 - t > maxAge) ? 'yes' : 'no';

/* ==================================================================
   Bus Moved · On home or work Wi-Fi: remember where that is
   A running average of the positions seen there (BusHomeAt,
   BusWorkAt), so which side of a road heads home or to work can be
   worked out. Inputs: gl_latitude, gl_longitude (from moved.js)
   ================================================================== */
// A Tasker global variable, trimmed, or '' if it isn't set (Tasker leaves an unset variable as its own
// name, starting with %)
function get(n) { var v = global(n); return (v === undefined || v === null || String(v).charAt(0) === '%') ? '' : String(v).trim(); }
// One of this task's local variables (Tasker passes them in as plain variables), trimmed, or '' if it
// isn't set
function loc(n) { try { var v = eval('typeof ' + n + ' === "undefined" ? "" : ' + n); return (v === null || String(v).charAt(0) === '%') ? '' : String(v).trim(); } catch (e) { return ''; } }
var wifi = get('BusStateWifi');
var which = wifi && wifi === get('BusHomeWifi') ? 'BusHomeAt' : wifi && wifi === get('BusWorkWifi') ? 'BusWorkAt' : '';
var lat = parseFloat(loc('gl_latitude')); var lon = parseFloat(loc('gl_longitude'));
if (which && !isNaN(lat) && !isNaN(lon)) {
  var at = null; try { at = JSON.parse(get(which) || 'null'); } catch (e) {}
  var n = at && at.n ? Math.min(at.n, 9) : 0;
  at = n ? { lat: (at.lat * n + lat) / (n + 1), lon: (at.lon * n + lon) / (n + 1), n: n + 1 } : { lat: lat, lon: lon, n: 1 };
  setGlobal(which, JSON.stringify({ lat: +at.lat.toFixed(6), lon: +at.lon.toFixed(6), n: at.n }));
}

/* ==================================================================
   Bus Watch · Where are you in a trip, and what should the island do?
   Used by Bus Moved (each pushed position) and Bus Watch (screen on, or
   run by hand). BusPlaces has one line per saved stop: "bus|id|name|
   lat|lon|radius" (no radius means BusNearRadius).

   A trip is a small state machine (BusStateTrip), so each position only
   has to answer "from where we are, does this move us on?":
     idle     no island. At a stop and slowed down -> at stop (start).
              Heading for a stop, due within a few minutes -> heading.
     heading  island showing, not there yet. Reached it and slowed ->
              at stop. Passed it or turned away, or on a bus going away,
              or got off well short of it (walking, over twice the
              minutes-ahead setting away, three checks running) -> left.
     at stop  waiting. On a bus heading away -> on bus (end). Walking
              steadily away, or past the end distance -> left (end).
     on bus   riding (no island, unless a saved stop is coming up on the
              route). Walking pace again -> left.
     left     island gone. That stop only starts again once you've come
              back 100 m from the furthest you went, or after 15 minutes.
              Other stops are free.
   Ending by swiping, timing out or getting home also moves to "left".

   Decisions use a sliding window of the last 6 positions
   (BusStateWindow): speed is the median of the last three readings
   (Android's own, or worked out from the window), and "moving away" is
   the trend of your distance from the stop across the window, not one
   jump. Poor fixes (over 25 m accuracy) are averaged with the previous
   one. On a bus, stops ahead are found by projecting you onto the
   route's line of stops (BusCacheSeq), not by compass direction.

   Swiping the island away snoozes everything (BusStateSnooze) until
   you've been to that stop and left it, clear of all your stops, or for
   30 minutes (a run by hand ignores that). Just off a bus, or on one,
   the stop by home or work never pops up: you've arrived. How often
   Android pushes positions follows the state as well.
   Output: busaction (start / approach / stop / none), busnote (what it
