    x = x.map(function (v, j) { return v + K[j][0] * y0 + K[j][1] * y1; });
    var IKH = [1 - K[0][0], -K[0][1], 0, 0, -K[1][0], 1 - K[1][1], 0, 0, -K[2][0], -K[2][1], 1, 0, -K[3][0], -K[3][1], 0, 1];
