lines.push('Wi-Fi now: ' + (ssidNow && !/^<unknown ssid>$/i.test(ssidNow) ? ssidNow + (ssidNow === get('BusWorkWifi') ? ' (work)' : ssidNow === get('BusHomeWifi') ? ' (home)' : '') : 'not connected'));
